mapper.update:
UPDATE edu.quizzes
SET lifecycle_status = #{nextStatus, javaType=edu.ai.lms.core.quiz.app.domain.QuizLifecycleStatus, typeHandler=org.apache.ibatis.type.EnumTypeHandler},
    display = #{display},
    version = version + 1,
    published_by = #{publishedBy},
    published_at = #{publishedAt},
    updated_at = NOW()
WHERE id = #{quizId}
  AND course_id = #{courseId}
  AND lifecycle_status = #{expectedStatus, javaType=edu.ai.lms.core.quiz.app.domain.QuizLifecycleStatus, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
  AND version = #{expectedVersion}

UPDATE edu.quizzes
SET version = version + 1,
    updated_at = NOW()
WHERE id = #{quizId}
  AND course_id = #{courseId}
  AND lifecycle_status = #{expectedStatus, javaType=edu.ai.lms.core.quiz.app.domain.QuizLifecycleStatus, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
  AND version = #{expectedVersion}

mapper.select:
SELECT id, quiz_title, description, unlimited, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, created_at, updated_at
SELECT id, quiz_title, unlimited, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, lifecycle_status, source_type, original_quiz_id, version, published_by, published_at, created_at, updated_at
FROM edu.quizzes
WHERE id = #{quizId}
  AND course_id = #{courseId}

SELECT id, quiz_title, unlimited, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, lifecycle_status, source_type, original_quiz_id, version, published_by, published_at, created_at, updated_at
SELECT id, quiz_title, description, unlimited, time_limit_minutes, pass_score, start_time, due_time, attempt_limited, course_id, student_id, teacher_id, display, created_at, updated_at
FROM edu.quizzes
WHERE course_id = #{courseId}
  AND student_id = #{studentId}
ORDER BY created_at DESC
